import XCTest
@testable import MeshLinkCore

final class CrossPlatformCompatibilityTests: XCTestCase {

    /**
     * Verifies that raw JSON generated by Android Kotlinx Serialization / Gson
     * is 100% properly decoded by the iOS Swift Codable parser.
     */
    func testAndroidJsonToIosPacketDecoding() {
        let androidJson = """
        {
            "messageId": "MSG-A1B2C3",
            "sourceId": "NODE-ANDROID-1",
            "sourceName": "Android Pixel",
            "destinationId": "NODE-IOS-1",
            "destinationName": "iPhone 15",
            "payload": "Hello from Android to iOS!",
            "ttl": 5,
            "hopCount": 0,
            "timestamp": 1700000000000,
            "routeHistory": ["NODE-ANDROID-1"],
            "previousHopId": "NODE-ANDROID-1"
        }
        """

        let packet = PacketSerializer.jsonToPacket(androidJson)
        XCTAssertNotNil(packet, "iOS should decode Android JSON packet")

        XCTAssertEqual(packet?.messageId, "MSG-A1B2C3")
        XCTAssertEqual(packet?.sourceId, "NODE-ANDROID-1")
        XCTAssertEqual(packet?.sourceName, "Android Pixel")
        XCTAssertEqual(packet?.destinationId, "NODE-IOS-1")
        XCTAssertEqual(packet?.destinationName, "iPhone 15")
        XCTAssertEqual(packet?.payload, "Hello from Android to iOS!")
        XCTAssertEqual(packet?.ttl, 5)
        XCTAssertEqual(packet?.hopCount, 0)
        XCTAssertEqual(packet?.timestamp, 1700000000000)
        XCTAssertEqual(packet?.routeHistory, ["NODE-ANDROID-1"])
        XCTAssertEqual(packet?.previousHopId, "NODE-ANDROID-1")
    }

    /**
     * Verifies that an iOS-generated packet matches the wire fields expected by Android.
     */
    func testIosPacketToAndroidJsonEncoding() {
        let packet = MessagePacket(
            messageId: "MSG-IOS-999",
            sourceId: "NODE-IOS-1",
            sourceName: "iPhone 15",
            destinationId: "NODE-ANDROID-2",
            destinationName: "Android Galaxy",
            payload: "Cross-platform relay test",
            ttl: 4,
            hopCount: 1,
            timestamp: 1710000000000,
            routeHistory: ["NODE-ORIGIN", "NODE-IOS-1"],
            previousHopId: "NODE-IOS-1"
        )

        guard let jsonString = PacketSerializer.packetToJson(packet) else {
            XCTFail("Failed to serialize iOS packet")
            return
        }

        XCTAssertTrue(jsonString.contains("\"messageId\":\"MSG-IOS-999\""))
        XCTAssertTrue(jsonString.contains("\"sourceId\":\"NODE-IOS-1\""))
        XCTAssertTrue(jsonString.contains("\"destinationId\":\"NODE-ANDROID-2\""))
        XCTAssertTrue(jsonString.contains("\"payload\":\"Cross-platform relay test\""))
        XCTAssertTrue(jsonString.contains("\"ttl\":4"))
        XCTAssertTrue(jsonString.contains("\"hopCount\":1"))
        XCTAssertTrue(jsonString.contains("\"routeHistory\":[\"NODE-ORIGIN\",\"NODE-IOS-1\"]"))
    }

    /**
     * Verifies full multi-hop forwarding logic across:
     * Android A -> iPhone B (Relay) -> Android C (Destination)
     */
    func testAndroidToIosRelayToAndroidMultiHopFlow() {
        let androidPacketJson = """
        {
            "messageId": "MSG-XPLAT-777",
            "sourceId": "NODE-A",
            "sourceName": "Android A (Pixel)",
            "destinationId": "NODE-C",
            "destinationName": "Android C (Galaxy)",
            "payload": "Cross-platform multi-hop via iPhone B",
            "ttl": 5,
            "hopCount": 0,
            "timestamp": 1705000000000,
            "routeHistory": ["NODE-A"],
            "previousHopId": "NODE-A"
        }
        """

        guard let packetFromA = PacketSerializer.jsonToPacket(androidPacketJson) else {
            XCTFail("Failed to decode packet from Android A")
            return
        }

        // iPhone B (Relay) processing
        let relayEngineB = RoutingEngine()
        let neighborsB = [
            Node(nodeId: "NODE-A", nodeName: "Android A", status: .connected),
            Node(nodeId: "NODE-C", nodeName: "Android C", status: .connected)
        ]

        let decisionB = relayEngineB.processIncomingPacket(
            packet: packetFromA,
            currentNodeId: "NODE-B",
            connectedNeighbors: neighborsB
        )

        switch decisionB {
        case .forward(let forwardedPacket, let candidateNextHops, _):
            XCTAssertEqual(forwardedPacket.ttl, 4, "TTL must be decremented by 1")
            XCTAssertEqual(forwardedPacket.hopCount, 1, "Hop count must be incremented by 1")
            XCTAssertEqual(forwardedPacket.routeHistory, ["NODE-A", "NODE-B"], "Relay node B must append itself to routeHistory")
            XCTAssertEqual(forwardedPacket.previousHopId, "NODE-B", "previousHopId must be set to relay node B")
            XCTAssertEqual(candidateNextHops, ["NODE-C"], "Next hop candidate must target Node C and exclude Node A")

            // Android C receives forwarded packet
            let destEngineC = RoutingEngine()
            let neighborsC = [Node(nodeId: "NODE-B", nodeName: "iPhone B", status: .connected)]
            let decisionC = destEngineC.processIncomingPacket(
                packet: forwardedPacket,
                currentNodeId: "NODE-C",
                connectedNeighbors: neighborsC
            )

            switch decisionC {
            case .deliver(let deliveredPacket, _):
                XCTAssertEqual(deliveredPacket.messageId, "MSG-XPLAT-777")
                XCTAssertEqual(deliveredPacket.payload, "Cross-platform multi-hop via iPhone B")
                XCTAssertEqual(deliveredPacket.hopCount, 1)
            default:
                XCTFail("Node C should have delivered packet")
            }

        default:
            XCTFail("iPhone B should have forwarded packet")
        }
    }
}
